select * from (select case when amount >= 3900 then 'high' when amount >= 1600 then 'mid' else 'low' end as amount_bucket, month(txn_time) as txn_month, min(txn_time) as min_txn_time, round((100 * sum(case when txn_type = 'REFUND' then 1 else 0 end)) / count(*), 1) as pct_refund from transactions group by case when amount >= 3900 then 'high' when amount >= 1600 then 'mid' else 'low' end, month(txn_time)) as agg where pct_refund >= 52 order by amount_bucket, txn_month desc
